import type { Example } from "../example.ts"
import { tab, type TabProps } from "./tab.ts"
import { html, type TemplateResult } from "lit-html"

export type TabsProps = { label: string; tabs: TabProps[]; class?: string }

/** Apps put these classes on their own tab row (the track holding the tabs). */
export function tabsClass(): string {
  return "inline-flex gap-1 p-1 rounded-control bg-subtle"
}

export function tabs(props: TabsProps): TemplateResult {
  return html`<ul role="tablist" aria-label=${props.label} class="${tabsClass()} m-0 list-none ${props.class ?? ""}">${props.tabs.map(
    (item) => html`<li role="presentation" class="flex">${tab(item)}</li>`,
  )}</ul>`
}

const albums: TabProps = { id: "albums-tab", panel: "albums-panel", label: "Albums", state: "selected" }
const people: TabProps = { id: "people-tab", panel: "people-panel", label: "People", state: "unselected" }
const requests: TabProps = { id: "requests-tab", panel: "requests-panel", label: "Requests", state: "unselected", count: "3" }

export const examples: Example[] = [
  { label: "default", render: () => tabs({ label: "Album sections", tabs: [albums, people, requests] }) },
  { label: "second selected", render: () => tabs({ label: "Album sections", tabs: [{ ...albums, state: "unselected" }, { ...people, state: "selected" }, requests] }) },
]
